private val Green = BrandGreen
private val Gold = BrandGold
private val Paper = BrandSurface
private object Rte { const val LOGIN="login"; const val HOME="home"; const val PEOPLE="people"; const val HOUSES="houses"; const val SYNC="sync"; const val PROFILE="profile"; const val DETAIL="people/{comuneroId}"; const val FORM="people/form?comuneroId={comuneroId}"; const val HOUSE="house/{hogarId}" }

@Composable fun QuincheApp(main: MainViewModel) {
    MaterialTheme(colorScheme = lightColorScheme(primary=Green, secondary=Gold, background=Paper, surface=Color.White, onSurface=BrandNavy)) {
        val logged by main.isLoggedIn.collectAsStateWithLifecycle(); val user by main.session.collectAsStateWithLifecycle(); val online by main.isOnline.collectAsStateWithLifecycle(); val pending by main.pendingCount.collectAsStateWithLifecycle(); val nav=rememberNavController()
        LaunchedEffect(logged) { nav.navigate(if(logged) Rte.HOME else Rte.LOGIN){ popUpTo(nav.graph.id){inclusive=true}; launchSingleTop=true } }
        NavHost(nav, if(logged) Rte.HOME else Rte.LOGIN) {
            composable(Rte.LOGIN){ LoginScreen() }
            composable(Rte.HOME){ Shell(nav,main,user,online,pending,"Inicio"){ Dashboard(nav) } }
            composable(Rte.PEOPLE){ Shell(nav,main,user,online,pending,"Comuneros"){ People(nav) } }
            composable(Rte.HOUSES){ Shell(nav,main,user,online,pending,"Hogares y censos",true){ Houses(nav) } }
            composable(Rte.SYNC){ Shell(nav,main,user,online,pending,"Sincronizar"){ SyncScreen(main) } }
            composable(Rte.PROFILE){ Shell(nav,main,user,online,pending,"Mi perfil"){ Profile(user,main::logout) } }
            composable(Rte.DETAIL,listOf(navArgument("comuneroId"){type=NavType.StringType})){ Shell(nav,main,user,online,pending,"Ficha del comunero",true){ PersonDetail(nav) } }
            composable(Rte.FORM,listOf(navArgument("comuneroId"){type=NavType.StringType;nullable=true;defaultValue=null})){ Shell(nav,main,user,online,pending,if(it.arguments?.getString("comuneroId")==null)"Nuevo comunero" else "Editar comunero",true){ PersonForm(nav) } }
            composable(Rte.HOUSE,listOf(navArgument("hogarId"){type=NavType.StringType})){ Shell(nav,main,user,online,pending,"Ficha del hogar",true){ HouseDetail() } }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable private fun Shell(nav:NavHostController,main:MainViewModel,user:SessionUser?,online:Boolean,pending:Int,title:String,back:Boolean=false,body: @Composable (PaddingValues)->Unit){
    val drawer=rememberDrawerState(DrawerValue.Closed);val scope=rememberCoroutineScope()
    ModalNavigationDrawer(drawerState=drawer,gesturesEnabled=!back,drawerContent={ModalDrawerSheet{
        Column(Modifier.padding(24.dp)){Text("SJQ",style=MaterialTheme.typography.headlineLarge,color=Green,fontWeight=FontWeight.Black);Text(user?.nombreCompleto.orEmpty(),fontWeight=FontWeight.Bold);Text(user?.role?.etiqueta.orEmpty(),color=Color.Gray)}
        DrawerItem(Icons.Default.Home,"Inicio"){scope.launch{drawer.close()};nav.navigate(Rte.HOME)}
        user?.role?.modulos?.forEach{m->DrawerItem(Icons.Default.Apps,m.label()){scope.launch{drawer.close()};if(m==AppModule.COMUNEROS)nav.navigate(Rte.PEOPLE)};if(m==AppModule.COMUNEROS)DrawerItem(Icons.Default.HolidayVillage,"Hogares y censos"){scope.launch{drawer.close()};nav.navigate(Rte.HOUSES)}}
        DrawerItem(Icons.Default.Sync,"Sincronizar"){scope.launch{drawer.close()};nav.navigate(Rte.SYNC)};DrawerItem(Icons.Default.Person,"Mi perfil"){scope.launch{drawer.close()};nav.navigate(Rte.PROFILE)};DrawerItem(Icons.AutoMirrored.Filled.ExitToApp,"Cerrar sesión",main::logout)
    }}){Scaffold(containerColor=Paper,topBar={BrandTopBar(title,online,back){if(back)nav.popBackStack()else scope.launch{drawer.open()}}},bottomBar={if(!back)NavigationBar(containerColor=Color.White){Bottom(nav,Rte.HOME,"Inicio",Icons.Default.Home);Bottom(nav,Rte.SYNC,if(pending>0)"Sincronizar ($pending)" else "Sincronizar",Icons.Default.Sync);Bottom(nav,Rte.PROFILE,"Mi perfil",Icons.Default.Person)}},content={padding->Box(Modifier.fillMaxSize().padding(padding)){body(PaddingValues(0.dp))}})}
}
@Composable private fun DrawerItem(icon:ImageVector,text:String,click:()->Unit)=NavigationDrawerItem({Text(text)},false,click,Modifier.padding(horizontal=12.dp),icon={Icon(icon,null)})
@Composable private fun RowScope.Bottom(nav:NavHostController,route:String,label:String,icon:ImageVector)=NavigationBarItem(nav.currentDestination?.route==route,{nav.navigate(route){launchSingleTop=true}},{Icon(icon,null)},label={Text(label)})

@Composable private fun LoginScreen(vm:LoginViewModel=viewModel(factory=LoginViewModel.Factory)){
    val username by vm.usuario.collectAsStateWithLifecycle();val state by vm.state.collectAsStateWithLifecycle();val errors by vm.fieldErrors.collectAsStateWithLifecycle();var pass by remember{mutableStateOf("")}
    LazyColumn(Modifier.fillMaxSize().background(Paper),horizontalAlignment=Alignment.CenterHorizontally){item{Column(Modifier.widthIn(max=520.dp)){PrototypeLoginHero();Card(Modifier.padding(horizontal=24.dp).offset(y=(-25).dp).fillMaxWidth(),shape=RoundedCornerShape(18.dp),colors=CardDefaults.cardColors(containerColor=Color.White),elevation=CardDefaults.cardElevation(10.dp)){Column(Modifier.padding(20.dp),verticalArrangement=Arrangement.spacedBy(13.dp)){Text("Iniciar sesión",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold,color=BrandNavy);Text("Ingrese sus datos para continuar",color=BrandMuted,fontSize=13.sp)
        OutlinedTextField(username,vm::onUsuarioChanged,Modifier.fillMaxWidth(),label={Text("Usuario")},leadingIcon={Icon(Icons.Default.PersonOutline,null,tint=BrandMuted)},isError=errors.usuario,supportingText={if(errors.usuario)Text("Ingrese su usuario")},singleLine=true,shape=RoundedCornerShape(10.dp))
        OutlinedTextField(pass,{pass=it;vm.onClaveChanged()},Modifier.fillMaxWidth(),label={Text("Contraseña")},leadingIcon={Icon(Icons.Default.Lock,null,tint=BrandMuted)},visualTransformation=PasswordVisualTransformation(),isError=errors.clave,supportingText={if(errors.clave)Text("Ingrese su contraseña")},singleLine=true,shape=RoundedCornerShape(10.dp))
        if(state is UiState.Error)Text((state as UiState.Error).message,color=MaterialTheme.colorScheme.error,fontSize=12.sp);Button({vm.login(pass)},Modifier.fillMaxWidth().height(50.dp),enabled=state !is UiState.Loading,shape=RoundedCornerShape(11.dp)){if(state is UiState.Loading)CircularProgressIndicator(Modifier.size(20.dp),strokeWidth=2.dp,color=Color.White)else{Text("Iniciar sesión",fontWeight=FontWeight.Bold);Spacer(Modifier.width(12.dp));Icon(Icons.Default.ArrowForward,null)}};OfflineNote()}}}}}
}

