@OptIn(ExperimentalMaterial3Api::class) @Composable private fun PersonForm(nav:NavHostController,vm:ComuneroFormViewModel=viewModel(factory=ComuneroFormViewModel.Factory)){val nombres by vm.nombres.collectAsStateWithLifecycle();val apellidos by vm.apellidos.collectAsStateWithLifecycle();val tel by vm.telefono.collectAsStateWithLifecycle();val mail by vm.correo.collectAsStateWithLifecycle();val code by vm.codigo.collectAsStateWithLifecycle();val status by vm.estado.collectAsStateWithLifecycle();val homes by vm.hogares.collectAsStateWithLifecycle();val homeId by vm.hogarId.collectAsStateWithLifecycle();val relation by vm.parentesco.collectAsStateWithLifecycle();val saving by vm.guardando.collectAsStateWithLifecycle();val errors by vm.errores.collectAsStateWithLifecycle();val snackbar=remember{SnackbarHostState()};var openHome by remember{mutableStateOf(false)};var openRel by remember{mutableStateOf(false)};LaunchedEffect(Unit){vm.events.collect{when(it){ComuneroFormEvent.Guardado->nav.popBackStack();is ComuneroFormEvent.Fallo->snackbar.showSnackbar("No se pudo guardar: ${it.mensaje}")}}};LaunchedEffect(errors){if(errors.isNotEmpty())snackbar.showSnackbar("Revise los campos marcados")};Scaffold(containerColor=Color.Transparent,snackbarHost={SnackbarHost(snackbar)}){inner->LazyColumn(Modifier.fillMaxSize().padding(inner),contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("Datos personales",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold)};item{Field("Nombres *",nombres,vm::onNombresChanged,error=errors[CampoComunero.NOMBRES]);Field("Apellidos *",apellidos,vm::onApellidosChanged,error=errors[CampoComunero.APELLIDOS]);Field("Teléfono",tel,vm::onTelefonoChanged,error=errors[CampoComunero.TELEFONO]);Field("Correo",mail,vm::onCorreoChanged,error=errors[CampoComunero.CORREO]);Field("Código",code,{},enabled=false,error=errors[CampoComunero.CODIGO])};item{ExposedDropdownMenuBox(openHome,{openHome=it}){OutlinedTextField(homes.firstOrNull{it.hogarId==homeId}?.let{"Casa ${it.numeroCasa} · ${it.sector}"}.orEmpty(),{},Modifier.menuAnchor().fillMaxWidth(),readOnly=true,label={Text("Hogar *")},isError=errors[CampoComunero.HOGAR]!=null,supportingText=errors[CampoComunero.HOGAR]?.let{{Text(it)}},trailingIcon={ExposedDropdownMenuDefaults.TrailingIcon(openHome)});ExposedDropdownMenu(openHome,{openHome=false}){homes.forEach{h->DropdownMenuItem({Text("Casa ${h.numeroCasa} · ${h.sector}")},{vm.onHogarSelected(h.hogarId);openHome=false})}}}};item{val opts=listOf("Responsable","Cónyuge","Hijo/a","Padre/Madre","Otro");ExposedDropdownMenuBox(openRel,{openRel=it}){OutlinedTextField(relation.orEmpty(),{},Modifier.menuAnchor().fillMaxWidth(),readOnly=true,label={Text("Parentesco")},isError=errors[CampoComunero.PARENTESCO]!=null,supportingText=errors[CampoComunero.PARENTESCO]?.let{{Text(it)}},trailingIcon={ExposedDropdownMenuDefaults.TrailingIcon(openRel)});ExposedDropdownMenu(openRel,{openRel=false}){opts.forEach{p->DropdownMenuItem({Text(p)},{vm.onParentescoSelected(p);openRel=false})}}}};item{SingleChoiceSegmentedButtonRow{EstadoComunero.entries.forEachIndexed{i,e->SegmentedButton(status==e,{vm.onEstadoSelected(e)},SegmentedButtonDefaults.itemShape(i,2)){Text(if(e==EstadoComunero.ACTIVO)"Activo" else "Inactivo")}}}};item{Row(horizontalArrangement=Arrangement.spacedBy(12.dp)){OutlinedButton({nav.popBackStack()},Modifier.weight(1f)){Text("Cancelar")};Button(vm::guardar,Modifier.weight(1f),enabled=!saving){if(saving)CircularProgressIndicator(Modifier.size(18.dp),strokeWidth=2.dp,color=Color.White)else Text("Guardar")}}}}}}
@Composable private fun Field(label:String,value:String,change:(String)->Unit,enabled:Boolean=true,error:String?=null)=OutlinedTextField(value,change,Modifier.fillMaxWidth(),label={Text(label)},enabled=enabled,isError=error!=null,supportingText=error?.let{{Text(it)}},singleLine=true)

