t.CheckCircle,Modifier.weight(1f));SystemStateCard("Almacenamiento local","Protegido",Icons.Default.Lock,Modifier.weight(1f))}};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Registros pendientes",fontWeight=FontWeight.Bold,color=BrandNavy,fontSize=17.sp);Text("$pending registros",color=BrandMuted,fontSize=12.sp)}};item{if(pending==0)Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp),border=androidx.compose.foundation.BorderStroke(1.dp,BrandLine),colors=CardDefaults.cardColors(containerColor=Color.White)){Column(Modifier.fillMaxWidth().padding(22.dp),horizontalAlignment=Alignment.CenterHorizontally){Box(Modifier.size(48.dp).background(BrandGreenSoft,CircleShape),contentAlignment=Alignment.Center){Icon(Icons.Default.Check,null,tint=Green)};Text("Todo sincronizado",fontWeight=FontWeight.Bold,color=BrandNavy);Text("No existen cambios locales pendientes.",color=BrandMuted,fontSize=11.sp)}}else Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp),border=androidx.compose.foundation.BorderStroke(1.dp,BrandLine),colors=CardDefaults.cardColors(containerColor=Color.White)){ListItem({Text("Cambios guardados en el dispositivo",fontWeight=FontWeight.Bold,fontSize=13.sp)},supportingContent={Text("$pending registros esperan ser enviados",fontSize=11.sp)},leadingContent={Box(Modifier.size(38.dp).background(BrandBlueSoft,RoundedCornerShape(10.dp)),contentAlignment=Alignment.Center){Icon(Icons.Default.Storage,null,tint=BrandBlue)}})}};item{Button(main::requestSync,Modifier.fillMaxWidth().height(50.dp),enabled=state!=SyncState.RUNNING&&main.isSyncConfigured,shape=RoundedCornerShape(11.dp)){Icon(Icons.Default.Sync,null);Spacer(Modifier.width(8.dp));Text(if(state==SyncState.RUNNING)"Sincronizando…" else "Sincronizar ahora",fontWeight=FontWeight.Bold)}};item{Surface(color=Color(0xFFFFFAF0),shape=RoundedCornerShape(12.dp),border=androidx.compose.foundation.BorderStroke(1.dp,Color(0xFFEADBB5))){Row(Modifier.padding(12.dp)){Box(Modif